mapper.sql:
WHERE sv.delete_yn = 'N'
  AND m.delete_yn  = 'N'

  AND sv.survey_master_id = #{search.surveyMasterId}


  AND m.site_id = #{search.siteId}


  AND sv.status = #{search.status}


  AND sv.use_yn = #{search.useYn}


  AND sv.survey_title LIKE CONCAT('%', #{search.keyword}, '%')

mapper.delete:
DELETE FROM tb_survey
 WHERE delete_yn = 'Y'
   AND updated_at <= #{cutoff}

mapper.select:
SELECT COUNT(*) FROM tb_survey
 WHERE delete_yn = 'Y'
   AND updated_at <= #{cutoff}
